1. using System.Collections.ObjectModel;
2. using System.IO;
3. using System.Windows;
4. using CommunityToolkit.Mvvm.ComponentModel;
5. using CommunityToolkit.Mvvm.Input;
6. using ABLogixGitManager.Models;
7. using ABLogixGitManager.Services;
8. 
9. namespace ABLogixGitManager.ViewModels;
10. 
11. /// <summary>
12. /// View model for the Settings / Dependency Center window.
13. /// Owns the dependency scan operation and exposes the results as an observable list.
14. /// </summary>
15. public partial class SettingsViewModel : ObservableObject
16. {
17.     private readonly DependencyCheckerService _checker = new();
18.     private readonly DependencyInstallerService _installer = new();
19.     private readonly AppConfigService _configService = new();
20. 
21.     /// <summary>Current path to l5xgit.exe, editable by the user in the Settings window.</summary>
22.     [ObservableProperty]
23.     private string _l5xGitExePath;
24. 
25.     /// <summary><c>true</c> while a dependency scan is in progress.</summary>
26.     [ObservableProperty]
27.     [NotifyCanExecuteChangedFor(nameof(InstallDotNetSdkCommand))]
28.     [NotifyCanExecuteChangedFor(nameof(InstallAndBuildRockwellVcsToolsCommand))]
29.     [NotifyCanExecuteChangedFor(nameof(RebuildRockwellVcsToolsCommand))]
30.     [NotifyCanExecuteChangedFor(nameof(InstallStudioCustomToolsMenuCommand))]
31.     [NotifyPropertyChangedFor(nameof(CanUseExistingL5xGit))]
32.     private bool _isScanning;
33. 
34.     /// <summary>Short status message shown above the dependency list.</summary>
35.     [ObservableProperty]
36.     private string _scanStatus = "Click Rescan to check dependencies.";
37. 
38.     /// <summary><c>true</c> while an install/build action is in progress.</summary>
39.     [ObservableProperty]
40.     [NotifyCanExecuteChangedFor(nameof(InstallDotNetSdkCommand))]
41.     [NotifyCanExecuteChangedFor(nameof(InstallAndBuildRockwellVcsToolsCommand))]
42.     [NotifyCanExecuteChangedFor(nameof(RebuildRockwellVcsToolsCommand))]
43.     [NotifyCanExecuteChangedFor(nameof(InstallStudioCustomToolsMenuCommand))]
44.     [NotifyPropertyChangedFor(nameof(CanUseExistingL5xGit))]
45.     private bool _isActionBusy;
46. 
47.     /// <summary>
48.     /// <c>true</c> when the last scan found a Ready .NET SDK 10. When set, the SDK
49.     /// install action is disabled because the prerequisite is already satisfied.
50.     /// </summary>
51.     [ObservableProperty]
52.     [NotifyCanExecuteChangedFor(nameof(InstallDotNetSdkCommand))]
53.     private bool _isDotNetSdkReady;
54. 
55.     /// <summary>
56.     /// <c>true</c> when the last scan found a Ready Rockwell VCS Tools (l5xgit). When set,
57.     /// the download/compile and use-existing actions are disabled — nothing more to install.
58.     /// </summary>
59.     [ObservableProperty]
60.     [NotifyCanExecuteChangedFor(nameof(InstallAndBuildRockwellVcsToolsCommand))]
61.     [NotifyPropertyChangedFor(nameof(CanUseExistingL5xGit))]
62.     private bool _isL5xGitReady;
63. 
64.     /// <summary>
65.     /// <c>true</c> when Studio 5000 is detected. Controls visibility/enabled state of the
66.     /// "Add Custom Tools to Studio 5000" action.
67.     /// </summary>
68.     [ObservableProperty]
69.     [NotifyCanExecuteChangedFor(nameof(InstallStudioCustomToolsMenuCommand))]
70.     private bool _isStudio5000Detected;
71. 
72.     /// <summary>
73.     /// <c>true</c> when the Rockwell VCS tools repository has already been cloned locally.
74.     /// Used to enable the Rebuild action, which is only meaningful once the source is present.
75.     /// </summary>
76.     [ObservableProperty]
77.     [NotifyCanExecuteChangedFor(nameof(RebuildRockwellVcsToolsCommand))]
78.     private bool _isVcsToolsRepoPresent;
79. 
80.     /// <summary>
81.     /// <c>true</c> when the "Use existing l5xgit.exe" action may run: no scan or install
82.     /// is in progress and l5xgit is not already Ready.
83.     /// </summary>
84.     public bool CanUseExistingL5xGit => !IsActionBusy && !IsScanning && !IsL5xGitReady;
85. 
86.     /// <summary>Short status line for install/build actions.</summary>
87.     [ObservableProperty]
88.     private string _actionStatus = "No setup action running.";
89. 
90.     /// <summary>Streaming output from install/build actions shown in the settings window.</summary>
91.     [ObservableProperty]
92.     private string _actionLogOutput = string.Empty;
93. 
94.     /// <summary>One row per dependency, displayed in order of importance.</summary>
95.     public ObservableCollection<DependencyItemViewModel> Dependencies { get; } = [];
96. 
97.     /// <summary>
98.     /// Initialises the view model with seed rows (all <see cref="DependencyStatus.Unknown"/>)
99.     /// so the list renders immediately before the first scan runs.
100.     /// </summary>
101.     /// <param name="currentL5xGitExePath">The l5xgit.exe path from the current configuration.</param>
102.     public SettingsViewModel(string currentL5xGitExePath)
103.     {
104.         _l5xGitExePath = currentL5xGitExePath;
105. 
106.         // Seed rows so the list renders immediately with Unknown status.
107.         Dependencies.Add(new DependencyItemViewModel(
108.             new DependencyInfo("Studio 5000 & Logix SDK", DependencyStatus.Unknown),
109.             "ACD conversion for commit and restore",
110.             "Studio 5000 V38+ and Logix Designer SDK 2.2+"));
111.         Dependencies.Add(new DependencyItemViewModel(
112.             new DependencyInfo(".NET SDK 10", DependencyStatus.Unknown),
113.             "building Rockwell VCS tools from source",
114.             ".NET SDK 10.0+"));
115.         Dependencies.Add(new DependencyItemViewModel(
116.             new DependencyInfo("Rockwell VCS Tools (l5xgit)", DependencyStatus.Unknown),
117.             "commit and pull/restore operations",
118.             "Compatible Rockwell l5xgit build (supports Studio 5000 V38+ / SDK 2.2+)"));
119.         Dependencies.Add(new DependencyItemViewModel(
120.             new DependencyInfo("Git for Windows", DependencyStatus.Unknown),
121.             "pull/restore operations",
122.             "Current Git for Windows 2.x release"));
123. 
124.         // Check immediately so the Rebuild button is enabled on first open if the repo exists.
125.         IsVcsToolsRepoPresent = Directory.Exists(
126.             Path.Combine(DependencyInstallerService.GetRockwellVcsRepoDirectory(), ".git"));
127. 
128.         AppLogger.Info($"SettingsViewModel initialised with l5xgit path: '{currentL5xGitExePath}'. VCS repo present: {IsVcsToolsRepoPresent}.");
129.     }
130. 
131.     // -------------------------------------------------------------------------
132.     // Commands
133.     // -------------------------------------------------------------------------
134. 
135.     /// <summary>
136.     /// Runs all dependency probes concurrently, then updates each row in the list.
137.     /// Sets all rows to <see cref="DependencyStatus.Scanning"/> immediately so the UI
138.     /// reflects progress before results arrive.
139.     /// </summary>
140.     [RelayCommand]
141.     private async Task RescanAsync()
142.     {
143.         if (IsScanning) return;
144. 
145.         IsScanning = true;
146.         ScanStatus = "Scanning…";
147.         AppLogger.Info("Dependency rescan requested by user.");
148. 
149.         // Mark all as scanning so the UI reflects progress immediately.
150.         foreach (var item in Dependencies)
151.             item.Status = DependencyStatus.Scanning;
152. 
153.         try
154.         {
155.             var allResultsTask = _checker.CheckAllAsync(l5xGitPath: L5xGitExePath);
156.             var studioResultTask = _checker.CheckStudio5000Async();
157.             await Task.WhenAll(allResultsTask, studioResultTask);
158.             var results = allResultsTask.Result;
159. 
160.             Application.Current.Dispatcher.Invoke(() =>
161.             {
162.                 for (int i = 0; i < results.Count && i < Dependencies.Count; i++)
163.                     Dependencies[i].ApplyResult(results[i]);
164. 
165.                 // Disable install actions for prerequisites that are already satisfied.
166.                 IsDotNetSdkReady = results.Any(
167.                     r => r.Name == ".NET SDK 10" && r.Status == DependencyStatus.Ready);
168.                 IsL5xGitReady = results.Any(
169.                     r => r.Name == "Rockwell VCS Tools (l5xgit)" && r.Status == DependencyStatus.Ready);
170.                 IsStudio5000Detected = studioResultTask.Result.Status == DependencyStatus.Ready;
171.                 IsVcsToolsRepoPresent = Directory.Exists(
172.                     Path.Combine(DependencyInstallerService.GetRockwellVcsRepoDirectory(), ".git"));
173. 
174.                 var readyCount = results.Count(r => r.Status == DependencyStatus.Ready);
175.                 ScanStatus = $"Scan complete — {readyCount} of {results.Count} dependencies ready.";
176.             });
177.         }
178.         catch (Exception ex)
179.         {
180.             ScanStatus = $"Scan failed: {ex.Message}";
181.             AppLogger.Error("Dependency scan failed.", ex);
182.         }
183.         finally
184.         {
185.             IsScanning = false;
186.         }
187.     }
188. 
189.     /// <summary>
190.     /// Installs the .NET 10 SDK for source-build workflows and rescans dependencies.
191.     /// </summary>
192.     [RelayCommand(CanExecute = nameof(CanInstallDotNetSdk))]
193.     private async Task InstallDotNetSdkAsync()
194.     {
195.         IsActionBusy = true;
196.         ActionStatus = "Installing .NET SDK 10...";
197.         AppendActionLog("[setup] Starting .NET SDK 10 install.");
198.         AppLogger.Info("InstallDotNetSdkAsync command started.");
199. 
200.         try
201.         {
202.             var result = await _installer.InstallDotNetSdk10Async(AppendActionLog);
203.             ActionStatus = result.Message;
204.             AppendActionLog(result.Success ? $"[done] {result.Message}" : $"[error] {result.Message}");
205.             AppLogger.Info($"InstallDotNetSdkAsync command completed. Success={result.Success}. Message={result.Message}");
206.         }
207.         catch (Exception ex)
208.         {
209.             ActionStatus = $"SDK install failed: {ex.Message}";
210.             AppendActionLog($"[error] SDK install failed: {ex.Message}");
211.             AppLogger.Error("InstallDotNetSdkAsync command failed.", ex);
212.         }
213.         finally
214.         {
215.             IsActionBusy = false;
216.         }
217. 
218.         await RescanAsync();
219.     }
220. 
221.     /// <summary>
222.     /// Clones/updates Rockwell VCS tools, builds l5xgit.exe, saves the detected path, and rescans dependencies.
223.     /// </summary>
224.     [RelayCommand(CanExecute = nameof(CanInstallRockwellVcsTools))]
225.     private async Task InstallAndBuildRockwellVcsToolsAsync()
226.     {
227.         IsActionBusy = true;
228.         ActionStatus = "Installing and building Rockwell VCS tools...";
229.         AppendActionLog("[setup] Starting Rockwell VCS tools install/build.");
230.         AppLogger.Info("InstallAndBuildRockwellVcsToolsAsync command started.");
231. 
232.         try
233.         {
234.             var result = await _installer.InstallAndBuildRockwellVcsToolsAsync(AppendActionLog);
235.             ActionStatus = result.Message;
236. 
237.             if (result.Success && !string.IsNullOrWhiteSpace(result.L5xGitExePath))
238.             {
239.                 SaveConfiguredL5xGitPath(result.L5xGitExePath);
240.                 ActionStatus = "Download + compile complete. l5xgit.exe was automatically associated.";
241.                 AppendActionLog($"[settings] Saved l5xgit.exe path: {result.L5xGitExePath}");
242.             }
243.             else
244.             {
245.                 AppendActionLog(result.Success ? $"[done] {result.Message}" : $"[error] {result.Message}");
246.             }
247. 
248.             AppLogger.Info($"InstallAndBuildRockwellVcsToolsAsync command completed. Success={result.Success}. Message={result.Message}");
249.         }
250.         catch (Exception ex)
251.         {
252.             ActionStatus = $"VCS tools setup failed: {ex.Message}";
253.             AppendActionLog($"[error] VCS tools setup failed: {ex.Message}");
254.             AppLogger.Error("InstallAndBuildRockwellVcsToolsAsync command failed.", ex);
255.         }
256.         finally
257.         {
258.             IsActionBusy = false;
259.         }
260. 
261.         await RescanAsync();
262.     }
263. 
264.     /// <summary>
265.     /// Forces a git pull + recompile of the already-cloned Rockwell VCS tools, then rescans.
266.     /// Available whenever the local repository clone exists, regardless of whether
267.     /// the current l5xgit.exe is functional. Use this to resolve SDK version mismatches.
268.     /// </summary>
269.     [RelayCommand(CanExecute = nameof(CanRebuildVcsTools))]
270.     private async Task RebuildRockwellVcsToolsAsync()
271.     {
272.         IsActionBusy = true;
273.         ActionStatus = "Rebuilding Rockwell VCS tools against local SDK...";
274.         AppendActionLog("[rebuild] Pulling latest source and rebuilding l5xgit.exe.");
275.         AppLogger.Info("RebuildRockwellVcsToolsAsync command started.");
276. 
277.         try
278.         {
279.             var result = await _installer.InstallAndBuildRockwellVcsToolsAsync(AppendActionLog);
280.             ActionStatus = result.Message;
281. 
282.             if (result.Success && !string.IsNullOrWhiteSpace(result.L5xGitExePath))
283.             {
284.                 SaveConfiguredL5xGitPath(result.L5xGitExePath);
285.                 ActionStatus = "Rebuild complete. l5xgit.exe was automatically associated.";
286.                 AppendActionLog($"[settings] Saved l5xgit.exe path: {result.L5xGitExePath}");
287.             }
288.             else
289.             {
290.                 AppendActionLog(result.Success ? $"[done] {result.Message}" : $"[error] {result.Message}");
291.             }
292. 
293.             AppLogger.Info($"RebuildRockwellVcsToolsAsync command completed. Success={result.Success}. Message={result.Message}");
294.         }
295.         catch (Exception ex)
296.         {
297.             ActionStatus = $"Rebuild failed: {ex.Message}";
298.             AppendActionLog($"[error] Rebuild failed: {ex.Message}");
299.             AppLogger.Error("RebuildRockwellVcsToolsAsync command failed.", ex);
300.         }
301.         finally
302.         {
303.             IsActionBusy = false;
304.         }
305. 
306.         await RescanAsync();
307.     }
308. 
309.     /// <summary>
310.     /// Installs Rockwell's CustomToolsMenu.xml into Studio 5000 common tools location.
311.     /// This action is only available when Studio 5000 is detected.
312.     /// </summary>
313.     [RelayCommand(CanExecute = nameof(CanInstallStudioCustomToolsMenu))]
314.     private async Task InstallStudioCustomToolsMenuAsync()
315.     {
316.         IsActionBusy = true;
317.         ActionStatus = "Installing Custom Tools menu into Studio 5000...";
318.         AppendActionLog("[setup] Starting Studio 5000 custom tools menu install.");
319.         AppLogger.Info("InstallStudioCustomToolsMenuAsync command started.");
320. 
321.         try
322.         {
323.             var result = await _installer.InstallStudioCustomToolsMenuAsync(AppendActionLog);
324.             ActionStatus = result.Message;
325.             AppendActionLog(result.Success ? $"[done] {result.Message}" : $"[error] {result.Message}");
326.             AppLogger.Info($"InstallStudioCustomToolsMenuAsync command completed. Success={result.Success}. Message={result.Message}");
327.         }
328.         catch (Exception ex)
329.         {
330.             ActionStatus = $"Studio custom tools menu install failed: {ex.Message}";
331.             AppendActionLog($"[error] Studio custom tools menu install failed: {ex.Message}");
332.             AppLogger.Error("InstallStudioCustomToolsMenuAsync command failed.", ex);
333.         }
334.         finally
335.         {
336.             IsActionBusy = false;
337.         }
338.     }
339. 
340.     /// <summary>
341.     /// Uses an already-compiled l5xgit.exe selected by the user, then rescans dependencies.
342.     /// </summary>
343.     public async Task SetExistingL5xGitPathAsync(string selectedExePath)
344.     {
345.         AppLogger.Info($"SetExistingL5xGitPathAsync called with path: {selectedExePath}");
346. 
347.         if (string.IsNullOrWhiteSpace(selectedExePath))
348.         {
349.             ActionStatus = "No file was selected.";
350.             AppendActionLog("[warning] No l5xgit.exe file was selected.");
351.             AppLogger.Warn("SetExistingL5xGitPathAsync aborted — empty path.");
352.             return;
353.         }
354. 
355.         if (!File.Exists(selectedExePath))
356.         {
357.             ActionStatus = $"Selected file does not exist: {selectedExePath}";
358.             AppendActionLog($"[error] File not found: {selectedExePath}");
359.             AppLogger.Warn($"SetExistingL5xGitPathAsync aborted — file not found: {selectedExePath}");
360.             return;
361.         }
362. 
363.         SaveConfiguredL5xGitPath(selectedExePath);
364.         ActionStatus = "Configured existing l5xgit.exe path.";
365.         AppendActionLog($"[done] Configured existing l5xgit.exe path: {selectedExePath}");
366. 
367.         await RescanAsync();
368.     }
369. 
370.     private bool CanInstallDotNetSdk() => !IsScanning && !IsActionBusy && !IsDotNetSdkReady;
371. 
372.     private bool CanInstallRockwellVcsTools() => !IsScanning && !IsActionBusy && !IsL5xGitReady;
373. 
374.     /// <summary>Rebuild is available any time the local clone exists and no operation is running.</summary>
375.     private bool CanRebuildVcsTools() => !IsScanning && !IsActionBusy && IsVcsToolsRepoPresent;
376. 
377.     private bool CanInstallStudioCustomToolsMenu() => !IsScanning && !IsActionBusy && IsStudio5000Detected;
378. 
379.     private void SaveConfiguredL5xGitPath(string l5xGitExePath)
380.     {
381.         var config = _configService.Load();
382.         config.L5xGitExePath = l5xGitExePath;
383.         _configService.Save(config);
384. 
385.         L5xGitExePath = l5xGitExePath;
386.         AppLogger.Info($"Saved l5xgit.exe path from Settings: {l5xGitExePath}");
387.     }
388. 
389.     private void AppendActionLog(string message)
390.     {
391.         var ts = DateTime.Now.ToString("HH:mm:ss");
392.         ActionLogOutput += $"[{ts}] {message}{Environment.NewLine}";
393.     }
394. }
