1. using System.Diagnostics;
2. using System.IO;
3. using System.Text.RegularExpressions;
4. using ABLogixGitManager.Models;
5. 
6. namespace ABLogixGitManager.Services;
7. 
8. /// <summary>
9. /// Shells out to <c>git</c> for read/write repository metadata operations: commit history,
10. /// branch listing, branch create/checkout/delete, and restoring working-tree files from a
11. /// specific historical commit. Complements <see cref="L5xGitCliService"/>, which owns the
12. /// <c>l5xgit</c>-orchestrated commit/restore workflow.
13. /// </summary>
14. /// <remarks>
15. /// Every public method logs its start, validation failures, and outcome to <see cref="AppLogger"/>.
16. /// All destructive operations (checkout, branch delete, commit-file restore) require the caller
17. /// to have already confirmed with the user; this service does not prompt.
18. /// </remarks>
19. public class GitRepositoryService
20. {
21.     // Field separator unlikely to appear in commit metadata; matches git's %x1f (unit separator).
22.     private const string FieldSeparator = "\u001f";
23. 
24.     // -------------------------------------------------------------------------
25.     // History
26.     // -------------------------------------------------------------------------
27. 
28.     /// <summary>
29.     /// Loads up to <paramref name="maxCount"/> commits across all branches, parsed from
30.     /// <c>git log --all --graph</c>, including the leading ASCII-art graph prefix git renders
31.     /// for each line.
32.     /// </summary>
33.     public async Task<List<GitCommitInfo>> GetCommitGraphAsync(
34.         string repoPath,
35.         int maxCount = 300,
36.         CancellationToken cancellationToken = default)
37.     {
38.         AppLogger.Info($"GetCommitGraphAsync starting for '{repoPath}' (max {maxCount}).");
39. 
40.         var commits = new List<GitCommitInfo>();
41. 
42.         if (!Directory.Exists(repoPath))
43.         {
44.             AppLogger.Warn($"GetCommitGraphAsync aborted — repo path not found: {repoPath}");
45.             return commits;
46.         }
47. 
48.         var format = string.Join(FieldSeparator, "%H", "%h", "%an", "%ad", "%s", "%D");
49. 
50.         var (exitCode, lines) = await RunCapturingAsync(
51.             [
52.                 "-C", repoPath,
53.                 "log", "--all", "--graph",
54.                 "--date=iso-strict",
55.                 $"--pretty=format:{format}",
56.                 $"--max-count={maxCount}",
57.             ],
58.             cancellationToken);
59. 
60.         if (exitCode != 0)
61.         {
62.             AppLogger.Warn($"GetCommitGraphAsync — git log exited with code {exitCode} for '{repoPath}'.");
63.             return commits;
64.         }
65. 
66.         // A commit's SHA is always exactly 40 hex characters; everything preceding it on the
67.         // first physical line of the formatted output is the ASCII graph prefix git inserted.
68.         var shaPattern = new Regex("^(?<prefix>[^0-9a-fA-F]*)(?<sha>[0-9a-fA-F]{40})$");
69. 
70.         foreach (var line in lines)
71.         {
72.             if (string.IsNullOrWhiteSpace(line))
73.                 continue;
74. 
75.             var fields = line.Split(FieldSeparator);
76.             if (fields.Length < 6)
77.                 continue; // Graph-only continuation line (no commit on it) — skip.
78. 
79.             var match = shaPattern.Match(fields[0]);
80.             if (!match.Success)
81.                 continue;
82. 
83.             commits.Add(new GitCommitInfo
84.             {
85.                 GraphPrefix = match.Groups["prefix"].Value,
86.                 Sha = match.Groups["sha"].Value,
87.                 ShortSha = fields[1],
88.                 Author = fields[2],
89.                 Date = fields[3],
90.                 Subject = fields[4],
91.                 RefNames = fields[5],
92.             });
93.         }
94. 
95.         AppLogger.Info($"GetCommitGraphAsync completed for '{repoPath}' — {commits.Count} commit(s) parsed.");
96.         return commits;
97.     }
98. 
99.     // -------------------------------------------------------------------------
100.     // Branches
101.     // -------------------------------------------------------------------------
102. 
103.     /// <summary>Lists local branches and remote-tracking branches, flagging the current branch.</summary>
104.     public async Task<List<GitBranchInfo>> GetBranchesAsync(
105.         string repoPath,
106.         CancellationToken cancellationToken = default)
107.     {
108.         AppLogger.Info($"GetBranchesAsync starting for '{repoPath}'.");
109. 
110.         var branches = new List<GitBranchInfo>();
111. 
112.         if (!Directory.Exists(repoPath))
113.         {
114.             AppLogger.Warn($"GetBranchesAsync aborted — repo path not found: {repoPath}");
115.             return branches;
116.         }
117. 
118.         var (localExitCode, localLines) = await RunCapturingAsync(
119.             ["-C", repoPath, "branch", "--list"], cancellationToken);
120. 
121.         if (localExitCode != 0)
122.         {
123.             AppLogger.Warn($"GetBranchesAsync — git branch --list exited with code {localExitCode} for '{repoPath}'.");
124.         }
125.         else
126.         {
127.             foreach (var line in localLines)
128.             {
129.                 if (string.IsNullOrWhiteSpace(line)) continue;
130.                 var isCurrent = line.StartsWith('*');
131.                 var name = line.TrimStart('*', '+', ' ').Trim();
132.                 if (name.Length == 0 || name.Contains("detached at") || name.Contains("detached from"))
133.                     continue;
134. 
135.                 branches.Add(new GitBranchInfo { Name = name, IsCurrent = isCurrent, IsRemote = false });
136.             }
137.         }
138. 
139.         var (remoteExitCode, remoteLines) = await RunCapturingAsync(
140.             ["-C", repoPath, "branch", "-r"], cancellationToken);
141. 
142.         if (remoteExitCode != 0)
143.         {
144.             AppLogger.Warn($"GetBranchesAsync — git branch -r exited with code {remoteExitCode} for '{repoPath}'.");
145.         }
146.         else
147.         {
148.             foreach (var line in remoteLines)
149.             {
150.                 var name = line.Trim();
151.                 if (name.Length == 0 || name.Contains("->"))
152.                     continue; // Skip the "origin/HEAD -> origin/main" alias line.
153. 
154.                 branches.Add(new GitBranchInfo { Name = name, IsCurrent = false, IsRemote = true });
155.             }
156.         }
157. 
158.         AppLogger.Info($"GetBranchesAsync completed for '{repoPath}' — {branches.Count} branch(es) found.");
159.         return branches;
160.     }
161. 
162.     /// <summary>
163.     /// Creates a new local branch. Fails with a user-visible message if the name is blank or
164.     /// already exists.
165.     /// </summary>
166.     public async Task<bool> CreateBranchAsync(
167.         string repoPath,
168.         string branchName,
169.         string? startPoint,
170.         Action<string> onOutput,
171.         CancellationToken cancellationToken = default)
172.     {
173.         AppLogger.Info($"CreateBranchAsync starting for '{branchName}' in '{repoPath}'.");
174. 
175.         if (string.IsNullOrWhiteSpace(branchName))
176.         {
177.             onOutput("[error] Branch name is required.");
178.             AppLogger.Warn("CreateBranchAsync failed — missing branch name.");
179.             return false;
180.         }
181. 
182.         var args = new List<string> { "-C", repoPath, "branch", branchName };
183.         if (!string.IsNullOrWhiteSpace(startPoint))
184.             args.Add(startPoint);
185. 
186.         var exitCode = await RunStreamingAsync(args, stdinInput: null, onOutput, cancellationToken);
187. 
188.         if (exitCode != 0)
189.         {
190.             AppLogger.Warn($"CreateBranchAsync failed — git branch exit code {exitCode} for '{branchName}'.");
191.             return false;
192.         }
193. 
194.         onOutput($"[done] Created branch: {branchName}");
195.         AppLogger.Info($"CreateBranchAsync completed for '{branchName}' in '{repoPath}'.");
196.         return true;
197.     }
198. 
199.     /// <summary>
200.     /// Checks out a branch. Blocks (returns <c>false</c> with a message) if the working tree has
201.     /// uncommitted changes, rather than silently discarding or stashing them. When
202.     /// <paramref name="isRemote"/> is <c>true</c>, <paramref name="branchName"/> must be a
203.     /// remote-tracking name (e.g. <c>origin/xyz</c>); a local tracking branch is created
204.     /// (<c>git checkout --track -b xyz origin/xyz</c>) unless a local branch with that short
205.     /// name already exists, in which case that local branch is checked out directly.
206.     /// </summary>
207.     public async Task<bool> CheckoutBranchAsync(
208.         string repoPath,
209.         string branchName,
210.         bool isRemote,
211.         Action<string> onOutput,
212.         CancellationToken cancellationToken = default)
213.     {
214.         AppLogger.Info($"CheckoutBranchAsync starting for '{branchName}' (remote: {isRemote}) in '{repoPath}'.");
215. 
216.         if (await HasUncommittedChangesAsync(repoPath, cancellationToken))
217.         {
218.             onOutput("[error] Working tree has uncommitted changes. Commit or discard them before switching branches.");
219.             AppLogger.Warn($"CheckoutBranchAsync blocked — uncommitted changes present in '{repoPath}'.");
220.             return false;
221.         }
222. 
223.         List<string> args;
224. 
225.         if (!isRemote)
226.         {
227.             args = ["-C", repoPath, "checkout", branchName];
228.         }
229.         else
230.         {
231.             var localName = branchName.Contains('/') ? branchName[(branchName.IndexOf('/') + 1)..] : branchName;
232.             var existingLocalBranches = await GetBranchesAsync(repoPath, cancellationToken);
233.             var localAlreadyExists = existingLocalBranches.Any(b => !b.IsRemote &&
234.                 string.Equals(b.Name, localName, StringComparison.Ordinal));
235. 
236.             args = localAlreadyExists
237.                 ? ["-C", repoPath, "checkout", localName]
238.                 : ["-C", repoPath, "checkout", "--track", "-b", localName, branchName];
239.         }
240. 
241.         var exitCode = await RunStreamingAsync(args, stdinInput: null, onOutput, cancellationToken);
242. 
243.         if (exitCode != 0)
244.         {
245.             AppLogger.Warn($"CheckoutBranchAsync failed — git checkout exit code {exitCode} for '{branchName}'.");
246.             return false;
247.         }
248. 
249.         onOutput($"[done] Checked out: {branchName}");
250.         AppLogger.Info($"CheckoutBranchAsync completed for '{branchName}' in '{repoPath}'.");
251.         return true;
252.     }
253. 
254.     /// <summary>
255.     /// Deletes a local branch. Refuses to delete the current branch. Attempts a safe delete
256.     /// (<c>git branch -d</c>) first; the caller must explicitly re-invoke with
257.     /// <paramref name="force"/> <c>true</c> after confirming with the user when the safe delete
258.     /// fails because the branch is not fully merged.
259.     /// </summary>
260.     public async Task<bool> DeleteBranchAsync(
261.         string repoPath,
262.         string branchName,
263.         bool force,
264.         Action<string> onOutput,
265.         CancellationToken cancellationToken = default)
266.     {
267.         AppLogger.Info($"DeleteBranchAsync starting for '{branchName}' (force: {force}) in '{repoPath}'.");
268. 
269.         var branches = await GetBranchesAsync(repoPath, cancellationToken);
270.         var target = branches.FirstOrDefault(b => !b.IsRemote &&
271.             string.Equals(b.Name, branchName, StringComparison.Ordinal));
272. 
273.         if (target is null)
274.         {
275.             onOutput($"[error] Local branch not found: {branchName}");
276.             AppLogger.Warn($"DeleteBranchAsync failed — branch not found: {branchName}");
277.             return false;
278.         }
279. 
280.         if (target.IsCurrent)
281.         {
282.             onOutput("[error] Cannot delete the currently checked-out branch. Switch to a different branch first.");
283.             AppLogger.Warn($"DeleteBranchAsync blocked — attempted to delete current branch '{branchName}'.");
284.             return false;
285.         }
286. 
287.         var deleteFlag = force ? "-D" : "-d";
288.         var exitCode = await RunStreamingAsync(
289.             ["-C", repoPath, "branch", deleteFlag, branchName], stdinInput: null, onOutput, cancellationToken);
290. 
291.         if (exitCode != 0)
292.         {
293.             AppLogger.Warn($"DeleteBranchAsync failed — git branch {deleteFlag} exit code {exitCode} for '{branchName}'.");
294.             return false;
295.         }
296. 
297.         onOutput($"[done] Deleted branch: {branchName}");
298.         AppLogger.Info($"DeleteBranchAsync completed for '{branchName}' in '{repoPath}'.");
299.         return true;
300.     }
