289.     private static string? DetectRegistryVersion(string[] keyPaths)
290.     {
291.         foreach (var path in keyPaths)
292.         {
293.             using var key = Registry.LocalMachine.OpenSubKey(path);
294.             if (key is null) continue;
295. 
296.             var version = key.GetValue("Version") as string
297.                 ?? key.GetValue("InstallVersion") as string;
298. 
299.             return version ?? "(version unknown)";
300.         }
301.         return null;
302.     }
303. 
304.     private static List<string> DetectRegistryVersions(string[] keyPaths)
305.     {
306.         var versions = new List<string>();
307.         foreach (var path in keyPaths)
308.         {
309.             using var key = Registry.LocalMachine.OpenSubKey(path);
310.             if (key is null)
311.                 continue;
312. 
313.             var version = key.GetValue("Version") as string
314.                 ?? key.GetValue("InstallVersion") as string;
315.             if (string.IsNullOrWhiteSpace(version))
316.                 continue;
317. 
318.             versions.Add(version.Trim());
319.         }
320. 
321.         return versions;
322.     }
323. 
324.     private static List<InstalledProductDetection> DetectInstalledProductsFromUninstall(params string[] nameTokens)
325.     {
326.         var detections = new List<InstalledProductDetection>();
327.         var hives = new[] { RegistryHive.LocalMachine, RegistryHive.CurrentUser };
328.         var views = new[] { RegistryView.Registry64, RegistryView.Registry32 };
329.         const string uninstallPath = @"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall";
330. 
331.         foreach (var hive in hives)
332.         {
333.             foreach (var view in views)
334.             {
335.                 try
336.                 {
337.                     using var baseKey = RegistryKey.OpenBaseKey(hive, view);
338.                     using var uninstallKey = baseKey.OpenSubKey(uninstallPath);
339.                     if (uninstallKey is null)
340.                         continue;
341. 
342.                     foreach (var subKeyName in uninstallKey.GetSubKeyNames())
343.                     {
344.                         using var subKey = uninstallKey.OpenSubKey(subKeyName);
345.                         var displayName = subKey?.GetValue("DisplayName") as string;
346.                         if (string.IsNullOrWhiteSpace(displayName))
347.                             continue;
348. 
349.                         var matches = nameTokens.Any(token =>
350.                             displayName.Contains(token, StringComparison.OrdinalIgnoreCase));
351.                         if (!matches)
352.                             continue;
353. 
354.                         var version =
355.                             subKey?.GetValue("DisplayVersion") as string ??
356.                             subKey?.GetValue("Version") as string ??
357.                             "(version unknown)";
358. 
359.                         detections.Add(new InstalledProductDetection(displayName, version.Trim()));
360.                     }
361.                 }
362.                 catch (Exception ex)
363.                 {
364.                     AppLogger.Warn($"Uninstall registry probe failed for {hive} {view}: {ex.Message}");
365.                 }
366.             }
367.         }
368. 
369.         return detections;
370.     }
371. 
372.     private sealed record InstalledProductDetection(string DisplayName, string Version);
373. 
374.     private static (string? DisplayName, string? Version) DetectInstalledProductFromUninstall(params string[] nameTokens)
375.     {
376.         var detection = DetectInstalledProductsFromUninstall(nameTokens).FirstOrDefault();
377.         return detection is null ? (null, null) : (detection.DisplayName, detection.Version);
378.     }
379. 
380.     internal static string? SelectPreferredStudioVersion(IEnumerable<string> versions)
381.     {
382.         var materialized = versions
383.             .Where(v => !string.IsNullOrWhiteSpace(v))
384.             .Select(v => v.Trim())
385.             .ToList();
386.         if (materialized.Count == 0)
387.             return null;
388. 
389.         var highestKnown = materialized
390.             .Select(v => (Version: v, Major: TryParseStudioMajor(v)))
391.             .Where(v => v.Major.HasValue)
392.             .OrderByDescending(v => v.Major!.Value)
393.             .ThenByDescending(v => v.Version, StringComparer.OrdinalIgnoreCase)
394.             .FirstOrDefault();
395.         if (highestKnown.Version is not null)
396.             return highestKnown.Version;
397. 
398.         // Fall back to the first value when no major can be parsed.
399.         return materialized[0];
400.     }
401. 
402.     private static string GetRockwellSdkPackageFeedPath()
403.     {
404.         return Path.Combine(
405.             Environment.GetFolderPath(Environment.SpecialFolder.CommonDocuments),
406.             "Studio 5000",
407.             "Logix Designer SDK",
408.             "dotnet");
409.     }
410. 
411.     private static string? TryParseVersion(string output)
412.     {
413.         var match = Regex.Match(output, @"\d+\.\d+(?:\.\d+)?(?:\.\d+)?");
414.         return match.Success ? match.Value : null;
415.     }
416. 
417.     /// <summary>
418.     /// Returns <c>true</c> when the version string indicates a Studio 5000 release older than V38.
419.     /// The VCS tools require Logix Designer V38+ and SDK 2.2+.
420.     /// </summary>
421.     internal static bool IsStudioVersionBelowMinimum(string version)
422.     {
423.         // Registry/uninstall versions are typically "38.00.00" or "36.00.00" style.
424.         // Extract the leading major number for comparison.
425.         var major = TryParseStudioMajor(version);
426.         if (major.HasValue)
427.             return major.Value < 38;
428. 
429.         // Cannot parse — don't flag it as incompatible; let the user discover it at runtime.
430.         return false;
431.     }
432. 
433.     private static int? TryParseStudioMajor(string version)
434.     {
435.         var match = Regex.Match(version.Trim(), @"(\d+)");
436.         if (match.Success && int.TryParse(match.Groups[1].Value, out var major))
437.             return major;
438. 
439.         return null;
440.     }
441. 
442.     /// <summary>
443.     /// Launches an executable with a single argument list, captures combined output,
444.     /// and returns the exit code and stdout (falls back to stderr if stdout is empty).
445.     /// </summary>
446.     private static async Task<(int ExitCode, string Output)> RunProbeAsync(
447.         string exe,
448.         IEnumerable<string> args,
449.         CancellationToken ct)
450.     {
451.         var psi = new ProcessStartInfo(exe)
452.         {
453.             UseShellExecute = false,
454.             CreateNoWindow = true,
455.             RedirectStandardOutput = true,
456.             RedirectStandardError = true,
457.         };
458. 
459.         foreach (var arg in args)
460.             psi.ArgumentList.Add(arg);
461. 
462.         using var process = Process.Start(psi)
463.             ?? throw new InvalidOperationException($"Failed to start process: {exe}");
464. 
465.         var stdout = process.StandardOutput.ReadToEndAsync(ct);
466.         var stderr = process.StandardError.ReadToEndAsync(ct);
467. 
468.         await Task.WhenAll(stdout, stderr);
469.         await process.WaitForExitAsync(ct);
470. 
471.         var output = string.IsNullOrWhiteSpace(stdout.Result) ? stderr.Result : stdout.Result;
472.         return (process.ExitCode, output.Trim());
473.     }
474. }
