1. using System.IO;
2. using ABLogixGitManager.Services;
3. 
4. namespace ABLogixGitManager.Tests;
5. 
6. /// <summary>
7. /// Integration tests for <see cref="GitRepositoryService"/> against real temporary git
8. /// repositories (no mocking of <c>git</c> itself), covering the commit graph, branch
9. /// management, and commit-restore behavior added for the Git History feature.
10. /// </summary>
11. public class GitRepositoryServiceTests
12. {
13.     private readonly GitRepositoryService _sut = new();
14. 
15.     [Fact]
16.     public async Task GetCommitGraphAsync_ParsesCommitsNewestFirst()
17.     {
18.         using var repo = new TempGitRepo();
19.         var first = repo.Commit("first commit");
20.         var second = repo.Commit("second commit");
21. 
22.         var commits = await _sut.GetCommitGraphAsync(repo.RepoPath);
23. 
24.         Assert.Equal(2, commits.Count);
25.         Assert.Equal(second, commits[0].Sha);
26.         Assert.Equal("second commit", commits[0].Subject);
27.         Assert.Equal(first, commits[1].Sha);
28.         Assert.Equal("first commit", commits[1].Subject);
29.         // Short SHA must be a genuine prefix of the full SHA, not an unrelated value.
30.         Assert.StartsWith(commits[0].ShortSha, commits[0].Sha, StringComparison.OrdinalIgnoreCase);
31.     }
32. 
33.     [Fact]
34.     public async Task GetCommitGraphAsync_ReturnsEmpty_WhenRepoPathDoesNotExist()
35.     {
36.         var commits = await _sut.GetCommitGraphAsync(System.IO.Path.Combine(Path.GetTempPath(), "does-not-exist-" + Guid.NewGuid()));
37. 
38.         Assert.Empty(commits);
39.     }
40. 
41.     [Fact]
42.     public async Task GetBranchesAsync_FlagsCurrentBranch()
43.     {
44.         using var repo = new TempGitRepo();
45.         repo.Commit("initial commit");
46. 
47.         var branches = await _sut.GetBranchesAsync(repo.RepoPath);
48. 
49.         var main = Assert.Single(branches, b => !b.IsRemote);
50.         Assert.Equal("main", main.Name);
51.         Assert.True(main.IsCurrent);
52.     }
53. 
54.     [Fact]
55.     public async Task GetRemotesAsync_ReturnsEmpty_WhenNoRemoteConfigured()
56.     {
57.         using var repo = new TempGitRepo();
58.         repo.Commit("initial commit");
59. 
60.         var remotes = await _sut.GetRemotesAsync(repo.RepoPath);
61. 
62.         Assert.Empty(remotes);
63.     }
64. 
65.     [Fact]
66.     public async Task GetRemotesAsync_ListsConfiguredRemotes()
67.     {
68.         using var repo = new TempGitRepo();
69.         using var origin = new TempGitRepo();
70.         repo.Commit("initial commit");
71.         repo.RunGit("remote", "add", "origin", origin.RepoPath);
72. 
73.         var remotes = await _sut.GetRemotesAsync(repo.RepoPath);
74. 
75.         Assert.Contains("origin", remotes);
76.     }
77. 
78.     [Fact]
79.     public async Task GetCurrentBranchNameAsync_ReturnsCheckedOutBranchName()
80.     {
81.         using var repo = new TempGitRepo();
82.         repo.Commit("initial commit");
83. 
84.         var branch = await _sut.GetCurrentBranchNameAsync(repo.RepoPath);
85. 
86.         Assert.Equal("main", branch);
87.     }
88. 
89.     [Fact]
90.     public async Task CreateBranchAsync_CreatesNewLocalBranch()
91.     {
92.         using var repo = new TempGitRepo();
93.         repo.Commit("initial commit");
94.         var log = new List<string>();
95. 
96.         var result = await _sut.CreateBranchAsync(repo.RepoPath, "feature/test", startPoint: null, onOutput: log.Add);
97. 
98.         Assert.True(result);
99.         var branches = await _sut.GetBranchesAsync(repo.RepoPath);
100.         Assert.Contains(branches, b => !b.IsRemote && b.Name == "feature/test" && !b.IsCurrent);
101.     }
102. 
103.     [Fact]
104.     public async Task CreateBranchAsync_FailsWithBlankName()
105.     {
106.         using var repo = new TempGitRepo();
107.         repo.Commit("initial commit");
108.         var log = new List<string>();
109. 
110.         var result = await _sut.CreateBranchAsync(repo.RepoPath, "   ", startPoint: null, onOutput: log.Add);
111. 
112.         Assert.False(result);
113.         Assert.Contains(log, l => l.Contains("required", StringComparison.OrdinalIgnoreCase));
114.     }
115. 
116.     [Fact]
117.     public async Task CheckoutBranchAsync_SwitchesCurrentBranch()
118.     {
119.         using var repo = new TempGitRepo();
120.         repo.Commit("initial commit");
121.         await _sut.CreateBranchAsync(repo.RepoPath, "feature/test", startPoint: null, onOutput: _ => { });
122. 
123.         var result = await _sut.CheckoutBranchAsync(repo.RepoPath, "feature/test", isRemote: false, onOutput: _ => { });
124. 
125.         Assert.True(result);
126.         var branches = await _sut.GetBranchesAsync(repo.RepoPath);
127.         Assert.Contains(branches, b => b.Name == "feature/test" && b.IsCurrent);
128.         Assert.Contains(branches, b => b.Name == "main" && !b.IsCurrent);
129.     }
130. 
131.     [Fact]
132.     public async Task CheckoutBranchAsync_BlocksWhenUncommittedChangesPresent()
133.     {
134.         using var repo = new TempGitRepo();
135.         repo.Commit("initial commit");
136.         await _sut.CreateBranchAsync(repo.RepoPath, "feature/test", startPoint: null, onOutput: _ => { });
137.         repo.WriteFile("dirty.txt", "uncommitted");
138.         var log = new List<string>();
139. 
140.         var result = await _sut.CheckoutBranchAsync(repo.RepoPath, "feature/test", isRemote: false, onOutput: log.Add);
141. 
142.         Assert.False(result);
143.         Assert.Contains(log, l => l.Contains("uncommitted", StringComparison.OrdinalIgnoreCase));
144.         var branches = await _sut.GetBranchesAsync(repo.RepoPath);
145.         Assert.Contains(branches, b => b.Name == "main" && b.IsCurrent);
146.     }
147. 
148.     [Fact]
149.     public async Task DeleteBranchAsync_BlocksDeletingCurrentBranch()
150.     {
151.         using var repo = new TempGitRepo();
152.         repo.Commit("initial commit");
153.         var log = new List<string>();
154. 
155.         var result = await _sut.DeleteBranchAsync(repo.RepoPath, "main", force: false, onOutput: log.Add);
156. 
157.         Assert.False(result);
158.         Assert.Contains(log, l => l.Contains("Cannot delete the currently checked-out branch", StringComparison.OrdinalIgnoreCase));
159.     }
160. 
161.     [Fact]
162.     public async Task DeleteBranchAsync_SafeDeleteFailsThenForceDeleteSucceeds_ForUnmergedBranch()
163.     {
164.         using var repo = new TempGitRepo();
165.         repo.Commit("initial commit");
166.         await _sut.CreateBranchAsync(repo.RepoPath, "feature/unmerged", startPoint: null, onOutput: _ => { });
167.         await _sut.CheckoutBranchAsync(repo.RepoPath, "feature/unmerged", isRemote: false, onOutput: _ => { });
168.         repo.Commit("unmerged work"); // Diverges feature/unmerged from main.
169.         await _sut.CheckoutBranchAsync(repo.RepoPath, "main", isRemote: false, onOutput: _ => { });
170. 
171.         var safeLog = new List<string>();
172.         var safeResult = await _sut.DeleteBranchAsync(repo.RepoPath, "feature/unmerged", force: false, onOutput: safeLog.Add);
173.         Assert.False(safeResult);
174. 
175.         var forceLog = new List<string>();
176.         var forceResult = await _sut.DeleteBranchAsync(repo.RepoPath, "feature/unmerged", force: true, onOutput: forceLog.Add);
177.         Assert.True(forceResult);
178. 
179.         var branches = await _sut.GetBranchesAsync(repo.RepoPath);
180.         Assert.DoesNotContain(branches, b => b.Name == "feature/unmerged");
181.     }
182. 
183.     [Fact]
184.     public async Task HasUncommittedChangesAsync_DetectsPendingChanges()
185.     {
186.         using var repo = new TempGitRepo();
187.         repo.Commit("initial commit");
188. 
189.         Assert.False(await _sut.HasUncommittedChangesAsync(repo.RepoPath));
190. 
191.         repo.WriteFile("new-file.txt", "content");
192. 
193.         Assert.True(await _sut.HasUncommittedChangesAsync(repo.RepoPath));
194.     }
195. 
196.     [Fact]
197.     public async Task RestoreCommitFilesAsync_RestoresFileContentWithoutMovingHead()
198.     {
199.         using var repo = new TempGitRepo();
200.         repo.WriteFile("data.txt", "version 1");
201.         var firstSha = repo.Commit("v1");
202. 
203.         repo.WriteFile("data.txt", "version 2");
204.         var secondSha = repo.Commit("v2");
205. 
206.         var result = await _sut.RestoreCommitFilesAsync(repo.RepoPath, firstSha, onOutput: _ => { });
207. 
208.         Assert.True(result);
209.         Assert.Equal("version 1", File.ReadAllText(Path.Combine(repo.RepoPath, "data.txt")));
210. 
211.         // HEAD must not move — restoring a commit's files is a working-tree-only operation.
212.         var headSha = repo.RunGit("rev-parse", "HEAD").Trim();
213.         Assert.Equal(secondSha, headSha);
214. 
215.         // The restored content is left as an uncommitted change, not auto-committed.
216.         Assert.True(await _sut.HasUncommittedChangesAsync(repo.RepoPath));
217.     }
218. 
219.     [Fact]
220.     public async Task RestoreCommitFilesAsync_FailsWithBlankSha()
221.     {
222.         using var repo = new TempGitRepo();
223.         repo.Commit("initial commit");
224.         var log = new List<string>();
225. 
226.         var result = await _sut.RestoreCommitFilesAsync(repo.RepoPath, "   ", onOutput: log.Add);
227. 
228.         Assert.False(result);
229.         Assert.Contains(log, l => l.Contains("No commit selected", StringComparison.OrdinalIgnoreCase));
230.     }
231. }
