 using System.IO;
 using ABLogixGitManager.Services;

 namespace ABLogixGitManager.Tests;

 /// <summary>
 /// Integration tests for <see cref="GitRepositoryService"/> against real temporary git
 /// repositories (no mocking of <c>git</c> itself), covering the commit graph, branch
 /// management, and commit-restore behavior added for the Git History feature.
 /// </summary>
 public class GitRepositoryServiceTests
 {
     private readonly GitRepositoryService _sut = new();

     [Fact]
     public async Task GetCommitGraphAsync_ParsesCommitsNewestFirst()
     {
         using var repo = new TempGitRepo();
         var first = repo.Commit("first commit");
         var second = repo.Commit("second commit");

         var commits = await _sut.GetCommitGraphAsync(repo.RepoPath);

         Assert.Equal(2, commits.Count);
         Assert.Equal(second, commits[0].Sha);
         Assert.Equal("second commit", commits[0].Subject);
         Assert.Equal(first, commits[1].Sha);
         Assert.Equal("first commit", commits[1].Subject);
         // Short SHA must be a genuine prefix of the full SHA, not an unrelated value.
         Assert.StartsWith(commits[0].ShortSha, commits[0].Sha, StringComparison.OrdinalIgnoreCase);
     }

     [Fact]
     public async Task GetCommitGraphAsync_ReturnsEmpty_WhenRepoPathDoesNotExist()
     {
         var commits = await _sut.GetCommitGraphAsync(System.IO.Path.Combine(Path.GetTempPath(), "does-not-exist-" + Guid.NewGuid()));

         Assert.Empty(commits);
     }

     [Fact]
     public async Task GetBranchesAsync_FlagsCurrentBranch()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");

         var branches = await _sut.GetBranchesAsync(repo.RepoPath);

         var main = Assert.Single(branches, b => !b.IsRemote);
         Assert.Equal("main", main.Name);
         Assert.True(main.IsCurrent);
     }

     [Fact]
     public async Task GetRemotesAsync_ReturnsEmpty_WhenNoRemoteConfigured()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");

         var remotes = await _sut.GetRemotesAsync(repo.RepoPath);

         Assert.Empty(remotes);
     }

     [Fact]
     public async Task GetRemotesAsync_ListsConfiguredRemotes()
     {
         using var repo = new TempGitRepo();
         using var origin = new TempGitRepo();
         repo.Commit("initial commit");
         repo.RunGit("remote", "add", "origin", origin.RepoPath);

         var remotes = await _sut.GetRemotesAsync(repo.RepoPath);

         Assert.Contains("origin", remotes);
     }

     [Fact]
     public async Task GetCurrentBranchNameAsync_ReturnsCheckedOutBranchName()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");

         var branch = await _sut.GetCurrentBranchNameAsync(repo.RepoPath);

         Assert.Equal("main", branch);
     }

     [Fact]
     public async Task CreateBranchAsync_CreatesNewLocalBranch()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");
         var log = new List<string>();

         var result = await _sut.CreateBranchAsync(repo.RepoPath, "feature/test", startPoint: null, onOutput: log.Add);

         Assert.True(result);
         var branches = await _sut.GetBranchesAsync(repo.RepoPath);
         Assert.Contains(branches, b => !b.IsRemote && b.Name == "feature/test" && !b.IsCurrent);
     }

     [Fact]
     public async Task CreateBranchAsync_FailsWithBlankName()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");
         var log = new List<string>();

         var result = await _sut.CreateBranchAsync(repo.RepoPath, "   ", startPoint: null, onOutput: log.Add);

         Assert.False(result);
         Assert.Contains(log, l => l.Contains("required", StringComparison.OrdinalIgnoreCase));
     }

     [Fact]
     public async Task CheckoutBranchAsync_SwitchesCurrentBranch()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");
         await _sut.CreateBranchAsync(repo.RepoPath, "feature/test", startPoint: null, onOutput: _ => { });

         var result = await _sut.CheckoutBranchAsync(repo.RepoPath, "feature/test", isRemote: false, onOutput: _ => { });

         Assert.True(result);
         var branches = await _sut.GetBranchesAsync(repo.RepoPath);
         Assert.Contains(branches, b => b.Name == "feature/test" && b.IsCurrent);
         Assert.Contains(branches, b => b.Name == "main" && !b.IsCurrent);
     }

     [Fact]
     public async Task CheckoutBranchAsync_BlocksWhenUncommittedChangesPresent()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");
         await _sut.CreateBranchAsync(repo.RepoPath, "feature/test", startPoint: null, onOutput: _ => { });
         repo.WriteFile("dirty.txt", "uncommitted");
         var log = new List<string>();

         var result = await _sut.CheckoutBranchAsync(repo.RepoPath, "feature/test", isRemote: false, onOutput: log.Add);

         Assert.False(result);
         Assert.Contains(log, l => l.Contains("uncommitted", StringComparison.OrdinalIgnoreCase));
         var branches = await _sut.GetBranchesAsync(repo.RepoPath);
         Assert.Contains(branches, b => b.Name == "main" && b.IsCurrent);
     }

     [Fact]
     public async Task DeleteBranchAsync_BlocksDeletingCurrentBranch()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");
         var log = new List<string>();

         var result = await _sut.DeleteBranchAsync(repo.RepoPath, "main", force: false, onOutput: log.Add);

         Assert.False(result);
         Assert.Contains(log, l => l.Contains("Cannot delete the currently checked-out branch", StringComparison.OrdinalIgnoreCase));
     }

     [Fact]
     public async Task DeleteBranchAsync_SafeDeleteFailsThenForceDeleteSucceeds_ForUnmergedBranch()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");
         await _sut.CreateBranchAsync(repo.RepoPath, "feature/unmerged", startPoint: null, onOutput: _ => { });
         await _sut.CheckoutBranchAsync(repo.RepoPath, "feature/unmerged", isRemote: false, onOutput: _ => { });
         repo.Commit("unmerged work"); // Diverges feature/unmerged from main.
         await _sut.CheckoutBranchAsync(repo.RepoPath, "main", isRemote: false, onOutput: _ => { });

         var safeLog = new List<string>();
         var safeResult = await _sut.DeleteBranchAsync(repo.RepoPath, "feature/unmerged", force: false, onOutput: safeLog.Add);
         Assert.False(safeResult);

         var forceLog = new List<string>();
         var forceResult = await _sut.DeleteBranchAsync(repo.RepoPath, "feature/unmerged", force: true, onOutput: forceLog.Add);
         Assert.True(forceResult);

         var branches = await _sut.GetBranchesAsync(repo.RepoPath);
         Assert.DoesNotContain(branches, b => b.Name == "feature/unmerged");
     }

     [Fact]
     public async Task HasUncommittedChangesAsync_DetectsPendingChanges()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");

         Assert.False(await _sut.HasUncommittedChangesAsync(repo.RepoPath));

         repo.WriteFile("new-file.txt", "content");

         Assert.True(await _sut.HasUncommittedChangesAsync(repo.RepoPath));
     }

     [Fact]
     public async Task RestoreCommitFilesAsync_RestoresFileContentWithoutMovingHead()
     {
         using var repo = new TempGitRepo();
         repo.WriteFile("data.txt", "version 1");
         var firstSha = repo.Commit("v1");

         repo.WriteFile("data.txt", "version 2");
         var secondSha = repo.Commit("v2");

         var result = await _sut.RestoreCommitFilesAsync(repo.RepoPath, firstSha, onOutput: _ => { });

         Assert.True(result);
         Assert.Equal("version 1", File.ReadAllText(Path.Combine(repo.RepoPath, "data.txt")));

         // HEAD must not move — restoring a commit's files is a working-tree-only operation.
         var headSha = repo.RunGit("rev-parse", "HEAD").Trim();
         Assert.Equal(secondSha, headSha);

         // The restored content is left as an uncommitted change, not auto-committed.
         Assert.True(await _sut.HasUncommittedChangesAsync(repo.RepoPath));
     }

     [Fact]
     public async Task RestoreCommitFilesAsync_FailsWithBlankSha()
     {
         using var repo = new TempGitRepo();
         repo.Commit("initial commit");
         var log = new List<string>();

         var result = await _sut.RestoreCommitFilesAsync(repo.RepoPath, "   ", onOutput: log.Add);

         Assert.False(result);
         Assert.Contains(log, l => l.Contains("No commit selected", StringComparison.OrdinalIgnoreCase));
     }
 }

