1. using System.Diagnostics;
2. using System.IO;
3. using System.Linq;
4. using ABLogixGitManager.Models;
5. 
6. namespace ABLogixGitManager.Services;
7. 
8. /// <summary>
9. /// Shells out to l5xgit.exe (and git) to perform commit and pull/restore operations.
10. /// All operations are async, respect cancellation, and stream stdout/stderr back to the
11. /// caller via the <paramref name="onOutput"/> callback.
12. /// </summary>
13. /// <remarks>
14. /// Every public method logs its start, completion, validation failures, and exit codes
15. /// to <see cref="AppLogger"/> so diagnostics are available even when the application
16. /// is run without a terminal.
17. /// </remarks>
18. public class L5xGitCliService
19. {
20.     // Read/write helper for remote/branch lookups and branch switching used by the restore
21.     // workflow below (kept separate since it owns generic git metadata, not the l5xgit CLI).
22.     private readonly GitRepositoryService _gitService = new();
23. 
24.     // -------------------------------------------------------------------------
25.     // Public API
26.     // -------------------------------------------------------------------------
27. 
28.     /// <summary>
29.     /// Validates paths, writes the _L5xGit.yml sidecar, then runs:
30.     ///   l5xgit commit --acd &lt;acdPath&gt;
31.     /// Pipes the commit message to stdin.
32.     /// </summary>
33.     /// <param name="repo">Repository entry containing ACD and git paths.</param>
34.     /// <param name="l5xGitExePath">Full path to l5xgit.exe.</param>
35.     /// <param name="commitMessage">Commit message text supplied by the user.</param>
36.     /// <param name="onOutput">Callback invoked for each line of stdout/stderr.</param>
37.     /// <param name="cancellationToken">Token to cancel the operation mid-flight.</param>
38.     /// <returns>
39.     /// The operation outcome, including <see cref="L5xGitOperationResult.GitRepositoryRequired"/>
40.     /// when the UI must offer repository setup choices.
41.     /// </returns>
42.     public async Task<L5xGitOperationResult> CommitAsync(
43.         RepoEntry repo,
44.         string l5xGitExePath,
45.         string commitMessage,
46.         Action<string> onOutput,
47.         CancellationToken cancellationToken = default)
48.     {
49.         AppLogger.Info($"CommitAsync starting for repo '{repo.Name}', ACD: {repo.AcdFilePath}");
50. 
51.         var validationResult = ValidatePaths(repo, l5xGitExePath, onOutput);
52.         if (validationResult != L5xGitOperationResult.Succeeded)
53.         {
54.             AppLogger.Warn($"CommitAsync aborted — path validation failed for repo '{repo.Name}'.");
55.             return validationResult;
56.         }
57. 
58.         EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);
59. 
60.         // Blank line after the message signals end-of-input to PromptForCommitMessage.
61.         var stdin = commitMessage.Trim() + "\n\n";
62. 
63.         int exitCode = await RunProcessAsync(
64.             exePath: l5xGitExePath,
65.             arguments: ["commit", "--acd", repo.AcdFilePath],
66.             stdinInput: stdin,
67.             onOutput: onOutput,
68.             cancellationToken: cancellationToken);
69. 
70.         AppLogger.Info($"CommitAsync finished for repo '{repo.Name}' — exit code {exitCode}.");
71.         return exitCode == 0
72.             ? L5xGitOperationResult.Succeeded
73.             : L5xGitOperationResult.Failed;
74.     }
75. 
76.     /// <summary>
77.     /// Initializes a git repository in the specified folder.
78.     /// </summary>
79.     public async Task<bool> InitializeGitRepositoryAsync(
80.         string repoPath,
81.         Action<string> onOutput,
82.         CancellationToken cancellationToken = default)
83.     {
84.         AppLogger.Info($"InitializeGitRepositoryAsync starting for '{repoPath}'.");
85. 
86.         if (!Directory.Exists(repoPath))
87.         {
88.             onOutput($"[error] Repository folder not found: {repoPath}");
89.             AppLogger.Warn($"InitializeGitRepositoryAsync failed — folder not found: {repoPath}");
90.             return false;
91.         }
92. 
93.         if (IsGitWorkingTree(repoPath))
94.         {
95.             onOutput($"[info] Git is already initialized at: {repoPath}");
96.             AppLogger.Info($"InitializeGitRepositoryAsync skipped — already initialized: {repoPath}");
97.             return true;
98.         }
99. 
100.         var exitCode = await RunProcessAsync(
101.             exePath: "git",
102.             arguments: ["-C", repoPath, "init"],
103.             stdinInput: null,
104.             onOutput: onOutput,
105.             cancellationToken: cancellationToken);
106. 
107.         if (exitCode != 0)
108.         {
109.             AppLogger.Warn($"InitializeGitRepositoryAsync failed — git init exit code {exitCode} for '{repoPath}'.");
110.             return false;
111.         }
112. 
113.         onOutput($"[done] Initialized Git repository in: {repoPath}");
114.         AppLogger.Info($"InitializeGitRepositoryAsync completed for '{repoPath}'.");
115.         return true;
116.     }
117. 
118.     /// <summary>
119.     /// Clones a repository into the specified destination folder.
120.     /// </summary>
121.     public async Task<bool> CloneRepositoryAsync(
122.         string remoteUrl,
123.         string destinationPath,
124.         Action<string> onOutput,
125.         CancellationToken cancellationToken = default)
126.     {
127.         AppLogger.Info($"CloneRepositoryAsync starting for '{remoteUrl}' -> '{destinationPath}'.");
128. 
129.         if (string.IsNullOrWhiteSpace(remoteUrl))
130.         {
131.             onOutput("[error] Clone URL is required.");
132.             AppLogger.Warn("CloneRepositoryAsync failed — missing remote URL.");
133.             return false;
134.         }
135. 
136.         if (string.IsNullOrWhiteSpace(destinationPath))
137.         {
138.             onOutput("[error] Destination folder is required.");
139.             AppLogger.Warn("CloneRepositoryAsync failed — missing destination path.");
140.             return false;
141.         }
142. 
143.         if (Directory.Exists(destinationPath) && Directory.EnumerateFileSystemEntries(destinationPath).Any())
144.         {
145.             onOutput($"[error] Destination folder is not empty: {destinationPath}");
146.             AppLogger.Warn($"CloneRepositoryAsync failed — destination not empty: {destinationPath}");
147.             return false;
148.         }
149. 
150.         Directory.CreateDirectory(destinationPath);
151. 
152.         var exitCode = await RunProcessAsync(
153.             exePath: "git",
154.             arguments: ["clone", remoteUrl, destinationPath],
155.             stdinInput: null,
156.             onOutput: onOutput,
157.             cancellationToken: cancellationToken);
158. 
159.         if (exitCode != 0)
160.         {
161.             AppLogger.Warn($"CloneRepositoryAsync failed — git clone exit code {exitCode} for '{remoteUrl}'.");
162.             return false;
163.         }
164. 
165.         onOutput($"[done] Cloned repository into: {destinationPath}");
166.         AppLogger.Info($"CloneRepositoryAsync completed for '{remoteUrl}'.");
167.         return true;
168.     }
169. 
170.     /// <summary>
171.     /// Optionally switches to <paramref name="branchName"/>, validates paths, pulls the latest
172.     /// changes (skipped entirely for a repository with no remote — restore then rebuilds from
173.     /// the local working tree as-is), and finally runs:
174.     ///   l5xgit restoreacd --acd &lt;acdPath&gt;
175.     /// Pipes "y" to stdin to confirm overwriting the existing ACD file.
176.     /// </summary>
177.     /// <remarks>
178.     /// A plain <c>git pull</c> fails with "no tracking information for the current branch" when
179.     /// the checked-out branch has no configured upstream (common right after <c>git init</c> +
180.     /// <c>git remote add</c>, or after checking out a new local branch by name). When that
181.     /// happens, this method retries once with an explicit <c>git pull &lt;remote&gt; &lt;branch&gt;</c>
182.     /// and — on success — records the tracking relationship via <c>git branch --set-upstream-to</c>
