 using System.Diagnostics;
 using System.IO;
 using System.Linq;
 using ABLogixGitManager.Models;

 namespace ABLogixGitManager.Services;

 /// <summary>
 /// Shells out to l5xgit.exe (and git) to perform commit and pull/restore operations.
 /// All operations are async, respect cancellation, and stream stdout/stderr back to the
 /// caller via the <paramref name="onOutput"/> callback.
 /// </summary>
 /// <remarks>
 /// Every public method logs its start, completion, validation failures, and exit codes
 /// to <see cref="AppLogger"/> so diagnostics are available even when the application
 /// is run without a terminal.
 /// </remarks>
 public class L5xGitCliService
 {
     // Read/write helper for remote/branch lookups and branch switching used by the restore
     // workflow below (kept separate since it owns generic git metadata, not the l5xgit CLI).
     private readonly GitRepositoryService _gitService = new();

     // -------------------------------------------------------------------------
     // Public API
     // -------------------------------------------------------------------------

     /// <summary>
     /// Validates paths, writes the _L5xGit.yml sidecar, then runs:
     ///   l5xgit commit --acd &lt;acdPath&gt;
     /// Pipes the commit message to stdin.
     /// </summary>
     /// <param name="repo">Repository entry containing ACD and git paths.</param>
     /// <param name="l5xGitExePath">Full path to l5xgit.exe.</param>
     /// <param name="commitMessage">Commit message text supplied by the user.</param>
     /// <param name="onOutput">Callback invoked for each line of stdout/stderr.</param>
     /// <param name="cancellationToken">Token to cancel the operation mid-flight.</param>
     /// <returns>
     /// The operation outcome, including <see cref="L5xGitOperationResult.GitRepositoryRequired"/>
     /// when the UI must offer repository setup choices.
     /// </returns>
     public async Task<L5xGitOperationResult> CommitAsync(
         RepoEntry repo,
         string l5xGitExePath,
         string commitMessage,
         Action<string> onOutput,
         CancellationToken cancellationToken = default)
     {
         AppLogger.Info($"CommitAsync starting for repo '{repo.Name}', ACD: {repo.AcdFilePath}");

         var validationResult = ValidatePaths(repo, l5xGitExePath, onOutput);
         if (validationResult != L5xGitOperationResult.Succeeded)
         {
             AppLogger.Warn($"CommitAsync aborted — path validation failed for repo '{repo.Name}'.");
             return validationResult;
         }

         EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);

         // Blank line after the message signals end-of-input to PromptForCommitMessage.
         var stdin = commitMessage.Trim() + "\n\n";

         int exitCode = await RunProcessAsync(
             exePath: l5xGitExePath,
             arguments: ["commit", "--acd", repo.AcdFilePath],
             stdinInput: stdin,
             onOutput: onOutput,
             cancellationToken: cancellationToken);

         AppLogger.Info($"CommitAsync finished for repo '{repo.Name}' — exit code {exitCode}.");
         return exitCode == 0
             ? L5xGitOperationResult.Succeeded
             : L5xGitOperationResult.Failed;
     }

     /// <summary>
     /// Initializes a git repository in the specified folder.
     /// </summary>
     public async Task<bool> InitializeGitRepositoryAsync(
         string repoPath,
         Action<string> onOutput,
         CancellationToken cancellationToken = default)
     {
         AppLogger.Info($"InitializeGitRepositoryAsync starting for '{repoPath}'.");

         if (!Directory.Exists(repoPath))
         {
             onOutput($"[error] Repository folder not found: {repoPath}");
             AppLogger.Warn($"InitializeGitRepositoryAsync failed — folder not found: {repoPath}");
             return false;
         }

         if (IsGitWorkingTree(repoPath))
         {
             onOutput($"[info] Git is already initialized at: {repoPath}");
             AppLogger.Info($"InitializeGitRepositoryAsync skipped — already initialized: {repoPath}");
             return true;
         }

         var exitCode = await RunProcessAsync(
             exePath: "git",
             arguments: ["-C", repoPath, "init"],
             stdinInput: null,
             onOutput: onOutput,
             cancellationToken: cancellationToken);

         if (exitCode != 0)
         {
             AppLogger.Warn($"InitializeGitRepositoryAsync failed — git init exit code {exitCode} for '{repoPath}'.");
             return false;
         }

         onOutput($"[done] Initialized Git repository in: {repoPath}");
         AppLogger.Info($"InitializeGitRepositoryAsync completed for '{repoPath}'.");
         return true;
     }

     /// <summary>
     /// Clones a repository into the specified destination folder.
     /// </summary>
     public async Task<bool> CloneRepositoryAsync(
         string remoteUrl,
         string destinationPath,
         Action<string> onOutput,
         CancellationToken cancellationToken = default)
     {
         AppLogger.Info($"CloneRepositoryAsync starting for '{remoteUrl}' -> '{destinationPath}'.");

         if (string.IsNullOrWhiteSpace(remoteUrl))
         {
             onOutput("[error] Clone URL is required.");
             AppLogger.Warn("CloneRepositoryAsync failed — missing remote URL.");
             return false;
         }

         if (string.IsNullOrWhiteSpace(destinationPath))
         {
             onOutput("[error] Destination folder is required.");
             AppLogger.Warn("CloneRepositoryAsync failed — missing destination path.");
             return false;
         }

         if (Directory.Exists(destinationPath) && Directory.EnumerateFileSystemEntries(destinationPath).Any())
         {
             onOutput($"[error] Destination folder is not empty: {destinationPath}");
             AppLogger.Warn($"CloneRepositoryAsync failed — destination not empty: {destinationPath}");
             return false;
         }

         Directory.CreateDirectory(destinationPath);

         var exitCode = await RunProcessAsync(
             exePath: "git",
             arguments: ["clone", remoteUrl, destinationPath],
             stdinInput: null,
             onOutput: onOutput,
             cancellationToken: cancellationToken);

         if (exitCode != 0)
         {
             AppLogger.Warn($"CloneRepositoryAsync failed — git clone exit code {exitCode} for '{remoteUrl}'.");
             return false;
         }

         onOutput($"[done] Cloned repository into: {destinationPath}");
         AppLogger.Info($"CloneRepositoryAsync completed for '{remoteUrl}'.");
         return true;
     }

     /// <summary>
     /// Optionally switches to <paramref name="branchName"/>, validates paths, pulls the latest
     /// changes (skipped entirely for a repository with no remote — restore then rebuilds from
     /// the local working tree as-is), and finally runs:
     ///   l5xgit restoreacd --acd &lt;acdPath&gt;
     /// Pipes "y" to stdin to confirm overwriting the existing ACD file.
     /// </summary>
     /// <remarks>
     /// A plain <c>git pull</c> fails with "no tracking information for the current branch" when
     /// the checked-out branch has no configured upstream (common right after <c>git init</c> +
     /// <c>git remote add</c>, or after checking out a new local branch by name). When that
     /// happens, this method retries once with an explicit <c>git pull &lt;remote&gt; &lt;branch&gt;</c>
     /// and — on success — records the tracking relationship via <c>git branch --set-upstream-to</c>
     /// so future plain pulls succeed without this fallback.
     /// </remarks>
     /// <param name="repo">Repository entry containing ACD and git paths.</param>
     /// <param name="l5xGitExePath">Full path to l5xgit.exe.</param>
     /// <param name="onOutput">Callback invoked for each line of stdout/stderr.</param>
     /// <param name="cancellationToken">Token to cancel the operation mid-flight.</param>
     /// <param name="branchName">
     /// Local or remote-tracking branch (as reported by <see cref="GitRepositoryService.GetBranchesAsync"/>)
     /// to build the ACD from. <c>null</c> restores from whatever branch is currently checked out.
     /// </param>
     public async Task<bool> PullAndRestoreAsync(
         RepoEntry repo,
         string l5xGitExePath,
         Action<string> onOutput,
         CancellationToken cancellationToken = default,
         string? branchName = null)
     {
         AppLogger.Info(
             $"PullAndRestoreAsync starting for repo '{repo.Name}', git repo: {repo.GitRepoPath}, " +
             $"branch: {branchName ?? "(current)"}");

         if (!ValidatePathsForRestore(repo, l5xGitExePath, onOutput))
         {
             AppLogger.Warn($"PullAndRestoreAsync aborted — path validation failed for repo '{repo.Name}'.");
             return false;
         }

         if (!string.IsNullOrWhiteSpace(branchName) &&
             !await SwitchToBranchAsync(repo.GitRepoPath, branchName, onOutput, cancellationToken))
         {
             return false;
         }

         var remotes = await _gitService.GetRemotesAsync(repo.GitRepoPath, cancellationToken);
         if (remotes.Count == 0)
         {
             onOutput("[git pull] No remote configured for this repository — restoring from the local working tree only.");
             AppLogger.Info($"PullAndRestoreAsync — no remote configured for '{repo.Name}'; skipping git pull.");
         }
         else
         {
             onOutput("[git pull] Pulling latest from remote...");
             int gitExitCode = await RunProcessAsync(
                 exePath: "git",
                 arguments: ["-C", repo.GitRepoPath, "pull"],
                 stdinInput: null,
                 onOutput: onOutput,
                 cancellationToken: cancellationToken);

             if (gitExitCode != 0)
                 gitExitCode = await RetryPullWithExplicitBranchAsync(repo.GitRepoPath, remotes, onOutput, cancellationToken);

             if (gitExitCode != 0)
             {
                 var msg = $"git pull failed (exit code {gitExitCode}). Restore cancelled to prevent overwriting with stale content.";
                 onOutput($"[abort] {msg}");
                 AppLogger.Error($"PullAndRestoreAsync — {msg} — repo '{repo.Name}'.");
                 return false;

