501.     /// </summary>
502.     private async Task RefreshRestoreBranchOptionsAsync()
503.     {
504.         RestoreBranchOptions.Clear();
505.         var current = new RestoreBranchOption { Display = "Current branch (HEAD)", Value = null };
506.         RestoreBranchOptions.Add(current);
507.         SelectedRestoreBranchOption = current;
508. 
509.         if (SelectedRepo is null || !L5xGitCliService.IsGitWorkingTree(SelectedRepo.GitRepoPath))
510.             return;
511. 
512.         try
513.         {
514.             var branches = await _gitService.GetBranchesAsync(SelectedRepo.GitRepoPath);
515.             foreach (var branch in branches)
516.             {
517.                 RestoreBranchOptions.Add(new RestoreBranchOption
518.                 {
519.                     Display = branch.IsCurrent ? $"{branch.Name} (current)" : branch.Name,
520.                     Value = branch.Name,
521.                     IsRemote = branch.IsRemote,
522.                 });
523.             }
524.         }
525.         catch (Exception ex)
526.         {
527.             AppLogger.Error($"Failed to load branches for the restore branch selector — repo '{SelectedRepo?.Name}'.", ex);
528.         }
529.     }
