     /// <summary>
     /// Reloads the branch drop-down for the Pull &amp; Restore card from the currently selected
     /// repo's git working tree. Always leaves a "current branch" option first so restoring works
     /// without picking one. Silently leaves only that default option if the repo path isn't a
     /// git working tree yet (e.g. a brand-new mapping that hasn't been initialized/cloned).
     /// </summary>
     private async Task RefreshRestoreBranchOptionsAsync()
     {
         RestoreBranchOptions.Clear();
         var current = new RestoreBranchOption { Display = "Current branch (HEAD)", Value = null };
         RestoreBranchOptions.Add(current);
         SelectedRestoreBranchOption = current;

         if (SelectedRepo is null || !L5xGitCliService.IsGitWorkingTree(SelectedRepo.GitRepoPath))
             return;

         try
         {
             var branches = await _gitService.GetBranchesAsync(SelectedRepo.GitRepoPath);
             foreach (var branch in branches)
             {
                 RestoreBranchOptions.Add(new RestoreBranchOption
                 {
                     Display = branch.IsCurrent ? $"{branch.Name} (current)" : branch.Name,
                     Value = branch.Name,
                     IsRemote = branch.IsRemote,
                 });
             }
         }
         catch (Exception ex)
         {
             AppLogger.Error($"Failed to load branches for the restore branch selector — repo '{SelectedRepo?.Name}'.", ex);
         }
     }

