465.     /// <summary>
466.     /// Determines whether a directory is a git working tree.
467.     /// </summary>
468.     public static bool IsGitWorkingTree(string repoPath)
469.     {
470.         if (!Directory.Exists(repoPath))
471.             return false;
472. 
473.         var dotGitPath = Path.Combine(repoPath, ".git");
474.         if (Directory.Exists(dotGitPath) || File.Exists(dotGitPath))
475.             return true;
476. 
477.         try
478.         {
479.             var psi = new ProcessStartInfo("git")
480.             {
481.                 UseShellExecute = false,
482.                 CreateNoWindow = true,
483.                 RedirectStandardOutput = true,
484.                 RedirectStandardError = true,
485.             };
486.             psi.ArgumentList.Add("-C");
487.             psi.ArgumentList.Add(repoPath);
488.             psi.ArgumentList.Add("rev-parse");
489.             psi.ArgumentList.Add("--show-toplevel");
490. 
491.             using var process = Process.Start(psi);
492.             if (process is null)
493.                 return false;
494. 
495.             var output = process.StandardOutput.ReadToEnd();
496.             process.WaitForExit();
497. 
498.             if (process.ExitCode != 0 || string.IsNullOrWhiteSpace(output))
499.                 return false;
500. 
501.             var selectedPath = Path.GetFullPath(repoPath)
502.                 .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
503.             var repositoryRoot = Path.GetFullPath(output.Trim())
504.                 .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
505. 
506.             return string.Equals(selectedPath, repositoryRoot, StringComparison.OrdinalIgnoreCase);
507.         }
508.         catch (Exception ex)
509.         {
510.             AppLogger.Error($"IsGitWorkingTree probe failed for '{repoPath}'.", ex);
511.             return false;
512.         }
513.     }
