92.     /// <summary>Captures just <paramref name="window"/> (small padding so shadows/borders aren't clipped).</summary>
93.     private static void Snapshot(AutomationElement window, string fileName)
94.         => WindowCapture.SaveWindow(window, Path.Combine(ScreenshotDir, fileName), paddingPx: 4);
95. 
96.     [Fact]
97.     public void CaptureWikiScreenshots()
98.     {
99.         var exePath = AppExeLocator.Find();
100.         _app = Application.Launch(exePath);
101.         _automation = new UIA3Automation();
102. 
103.         var mainWindow = _app.GetMainWindow(_automation, TimeSpan.FromSeconds(20))
104.             ?? throw new InvalidOperationException("Main window did not appear within 20s.");
105.         Retry.WhileFalse(() => mainWindow.FindFirstDescendant(cf => cf.ByAutomationId("RepoListBox")) is not null, TimeSpan.FromSeconds(10));
106.         Snapshot(mainWindow, "main-window-empty-selection.png");
107. 
108.         // ---- Add Controller dialog ----
109.         // AddEditRepoWindow is opened without an explicit Owner, so it won't show up in
110.         // mainWindow.ModalWindows — find it among the app's top-level windows instead.
111.         var addButton = mainWindow.FindFirstDescendant(cf => cf.ByAutomationId("AddControllerButton"))!.AsButton();
112.         addButton.Invoke();
113.         var addDialog = WaitForTopLevelWindow("Add / Edit Controller", TimeSpan.FromSeconds(10));
114.         Snapshot(addDialog, "add-edit-controller-dialog.png");
115.         addDialog.FindFirstDescendant(cf => cf.ByName("CANCEL"))!.AsButton().Invoke();
116.         Retry.WhileFalse(() => addDialog.IsOffscreen, TimeSpan.FromSeconds(10));
117. 
118.         // ---- Repo selected, action buttons enabled ----
119.         var repoList = mainWindow.FindFirstDescendant(cf => cf.ByAutomationId("RepoListBox"))!.AsListBox();
120.         repoList.Items[0].Select();
121.         var historyTab = mainWindow.FindFirstDescendant(cf => cf.ByAutomationId("WorkspaceTabHistoryButton"))!.AsTabItem();
122.         historyTab.Select();
123.         Retry.WhileFalse(() => historyTab.IsSelected, TimeSpan.FromSeconds(5));
124.         Snapshot(mainWindow, "main-window-controller-selected.png");
125. 
126.         // ---- Settings / Dependency Center ----
127.         var settingsButton = mainWindow.FindFirstDescendant(cf => cf.ByAutomationId("OpenSettingsButton"))!.AsButton();
128.         settingsButton.Invoke();
129.         var settingsWindow = WaitForModalWindow(mainWindow, "Dependencies — Studio 5000 Git Manager", TimeSpan.FromSeconds(10));
130.         Retry.WhileFalse(() => !settingsWindow.IsOffscreen, TimeSpan.FromSeconds(5));
131.         Thread.Sleep(1500); // let the dependency scan settle so the screenshot shows real results, not spinners
132.         Snapshot(settingsWindow, "settings-dependency-center.png");
133.         settingsWindow.FindFirstDescendant(cf => cf.ByName("CLOSE"))!.AsButton().Invoke();
134.         Retry.WhileFalse(() => settingsWindow.IsOffscreen, TimeSpan.FromSeconds(10));
135. 
136.         // ---- Git History tab ----
137.         var historyWindow = mainWindow;
138.         var commitListBox = Retry.WhileNull(
139.             () => historyWindow.FindFirstDescendant(cf => cf.ByAutomationId("CommitListView"))?.AsListBox(),
140.             TimeSpan.FromSeconds(10)).Result;
141.         Retry.WhileFalse(() => commitListBox!.Items.Length == 2, TimeSpan.FromSeconds(10));
142.         Snapshot(historyWindow, "git-history-window.png");
143. 
144.         // ---- Select a commit to show the Restore action enabled ----
145.         commitListBox!.Items[0].Select();
146.         var restoreButton = historyWindow.FindFirstDescendant(cf => cf.ByAutomationId("RestoreCommitButton"))!.AsButton();
147.         Retry.WhileFalse(() => restoreButton.IsEnabled, TimeSpan.FromSeconds(5));
148.         Snapshot(historyWindow, "git-history-commit-selected.png");
149. 
150.         // ---- New Branch dialog, with the start-point dropdown open ----
151.         var newBranchButton = historyWindow.FindFirstDescendant(cf => cf.ByAutomationId("NewBranchButton"))!.AsButton();
152.         newBranchButton.Invoke();
153.         var newBranchDialog = WaitForModalWindow(historyWindow, "New Branch", TimeSpan.FromSeconds(10));
154.         Snapshot(newBranchDialog, "new-branch-dialog.png");
155. 
156.         var startPointBox = newBranchDialog.FindFirstDescendant(cf => cf.ByAutomationId("StartPointBox"))!.AsComboBox();
157.         startPointBox.Expand();
158.         Retry.WhileFalse(
159.             () => startPointBox.Patterns.ExpandCollapse.Pattern.ExpandCollapseState.Value == FlaUI.Core.Definitions.ExpandCollapseState.Expanded,
160.             TimeSpan.FromSeconds(5));
161.         // The open drop-down list renders as its own separate Win32 popup window that extends below
162.         // the dialog's own bounds and that UI Automation doesn't expose as a discoverable top-level
163.         // window (a WPF Popup always creates a real HWND, but .Parent walks from its items stay
164.         // inside the ComboBox's own logical tree, and it's absent from GetAllTopLevelWindows too).
165.         // Capture the union of the dialog's and each visible item's on-screen bounds directly instead
166.         // of resolving to window handles — safe here because this runs immediately after the
167.         // interaction that opened the list, so nothing else can have been drawn on top of it yet.
168.         WindowCapture.SaveElementBoundsUnion(
169.             new AutomationElement[] { newBranchDialog }.Concat(startPointBox.Items),
170.             Path.Combine(ScreenshotDir, "new-branch-dialog-startpoint-dropdown-open.png"),
171.             paddingPx: 4);
172.         startPointBox.Collapse();
173. 
174.         newBranchDialog.FindFirstDescendant(cf => cf.ByAutomationId("CancelButton"))!.AsButton().Invoke();
175.         Retry.WhileFalse(() => newBranchDialog.IsOffscreen, TimeSpan.FromSeconds(10));
176. 
177.         var actionsTab = mainWindow.FindFirstDescendant(cf => cf.ByAutomationId("WorkspaceTabActionsButton"))!.AsTabItem();
178.         actionsTab.Select();
179.     }
180. 
181.     private Window WaitForTopLevelWindow(string title, TimeSpan timeout)
182.     {
183.         var deadline = DateTime.UtcNow + timeout;
184.         while (DateTime.UtcNow < deadline)
185.         {
186.             try
187.             {
188.                 var match = _app!.GetAllTopLevelWindows(_automation!).FirstOrDefault(w => w.Title == title);
189.                 if (match is not null)
190.                     return match;
191.             }
192.             catch (Exception)
193.             {
194.                 // The window tree can be transiently unstable mid-transition; keep polling.
195.             }
196. 
197.             Thread.Sleep(200);
198.         }
199. 
200.         throw new InvalidOperationException($"'{title}' window did not appear within {timeout.TotalSeconds}s.");
201.     }
