600.     private async Task<bool> EnsureGitRepositoryReadyAsync(bool forcePrompt = false)
601.     {
602.         if (SelectedRepo is null)
603.             return false;
604. 
605.         if (!forcePrompt && L5xGitCliService.IsGitWorkingTree(SelectedRepo.GitRepoPath))
606.             return true;
607. 
608.         AppLogger.Warn($"Commit preflight detected missing git repository at '{SelectedRepo.GitRepoPath}'.");
609.         OperationStatus = $"Commit blocked: repository setup required ({SelectedRepo.Name})";
610. 
611.         var choiceWindow = new GitRepositoryActionWindow
612.         {
613.             Owner = Application.Current.MainWindow,
614.         };
615. 
616.         if (choiceWindow.ShowDialog() != true || choiceWindow.SelectedAction is null)
617.         {
618.             AppendLog("[cancelled] Commit cancelled because the repository is not initialized.");
619.             OperationStatus = $"Commit cancelled: {SelectedRepo.Name}";
620.             AppLogger.Info("Commit cancelled — user declined git repository setup.");
621.             return false;
622.         }
623. 
624.         switch (choiceWindow.SelectedAction.Value)
625.         {
626.             case GitRepositoryAction.Initialize:
627.                 IsBusy = true;
628.                 _cts = new CancellationTokenSource();
629.                 try
630.                 {
631.                     OperationStatus = $"Repository setup step 1/1: Initializing git repository ({SelectedRepo.Name})";
632.                     AppendLog("[phase] Repository setup — initializing git repository.");
633.                     var initialized = await _cliService.InitializeGitRepositoryAsync(
634.                         SelectedRepo.GitRepoPath,
635.                         AppendLog,
636.                         _cts.Token);
637. 
638.                     if (initialized)
639.                     {
640.                         initialized = await _gitService.ApplyRecommendedWorkspaceGitSettingsAsync(
641.                             SelectedRepo.GitRepoPath,
642.                             SelectedRepo.GitUserNameOverride,
643.                             SelectedRepo.GitUserEmailOverride,
644.                             AppendLog,
645.                             _cts.Token);
646.                     }
647. 
648.                     OperationStatus = initialized
649.                         ? $"Repository initialized: {SelectedRepo.Name}"
650.                         : $"Repository initialization failed: {SelectedRepo.Name}";
651.                     return initialized;
652.                 }
653.                 catch (OperationCanceledException)
654.                 {
655.                     AppendLog("[cancelled] Git initialization was cancelled.");
656.                     OperationStatus = $"Repository initialization cancelled: {SelectedRepo.Name}";
657.                     AppLogger.Info($"Git initialization cancelled for '{SelectedRepo.Name}'.");
658.                     return false;
659.                 }
660.                 catch (Exception ex)
661.                 {
662.                     AppendLog($"[error] {ex.Message}");
663.                     OperationStatus = $"Repository initialization failed: {SelectedRepo.Name}";
664.                     AppLogger.Error($"Git initialization failed for repo '{SelectedRepo.Name}'.", ex);
665.                     return false;
666.                 }
667.                 finally
668.                 {
669.                     _cts?.Dispose();
670.                     _cts = null;
671.                     IsBusy = false;
672.                 }
673. 
674.             case GitRepositoryAction.Clone:
675.                 {
676.                     var cloneWindow = new CloneRepositoryWindow(SelectedRepo.GitRepoPath)
677.                     {
678.                         Owner = Application.Current.MainWindow,
679.                     };
680. 
681.                     if (cloneWindow.ShowDialog() != true)
682.                     {
683.                         AppendLog("[cancelled] Clone repository was cancelled.");
684.                         OperationStatus = $"Clone cancelled: {SelectedRepo.Name}";
685.                         AppLogger.Info("Clone repository setup cancelled by user.");
686.                         return false;
687.                     }
688. 
689.                     IsBusy = true;
690.                     _cts = new CancellationTokenSource();
691.                     try
692.                     {
693.                         OperationStatus = $"Repository setup step 1/1: Cloning repository ({SelectedRepo.Name})";
694.                         AppendLog("[phase] Repository setup — cloning repository.");
695.                         var cloned = await _cliService.CloneRepositoryAsync(
696.                             cloneWindow.RemoteUrl,
697.                             cloneWindow.DestinationPath,
698.                             AppendLog,
699.                             _cts.Token);
700. 
701.                         if (!cloned)
702.                         {
703.                             OperationStatus = $"Clone failed: {SelectedRepo.Name}";
704.                             return false;
705.                         }
706. 
707.                         if (!string.Equals(SelectedRepo.GitRepoPath, cloneWindow.DestinationPath, StringComparison.Ordinal))
708.                         {
709.                             SelectedRepo.GitRepoPath = cloneWindow.DestinationPath;
710.                             PersistConfig();
711.                             AppLogger.Info($"Updated repo git path after clone: {cloneWindow.DestinationPath}");
712.                         }
713. 
714.                         cloned = await _gitService.ApplyRecommendedWorkspaceGitSettingsAsync(
715.                             SelectedRepo.GitRepoPath,
716.                             SelectedRepo.GitUserNameOverride,
717.                             SelectedRepo.GitUserEmailOverride,
718.                             AppendLog,
719.                             _cts.Token);
720.                         if (!cloned)
721.                         {
722.                             OperationStatus = $"Repository clone completed, but git identity setup failed: {SelectedRepo.Name}";
723.                             return false;
724.                         }
725. 
726.                         OperationStatus = $"Repository cloned: {SelectedRepo.Name}";
727.                         return true;
728.                     }
729.                     catch (OperationCanceledException)
730.                     {
731.                         AppendLog("[cancelled] Clone repository was cancelled.");
732.                         OperationStatus = $"Clone cancelled: {SelectedRepo.Name}";
733.                         AppLogger.Info($"Clone repository cancelled for '{SelectedRepo.Name}'.");
734.                         return false;
735.                     }
736.                     catch (Exception ex)
737.                     {
738.                         AppendLog($"[error] {ex.Message}");
739.                         OperationStatus = $"Clone failed: {SelectedRepo.Name}";
740.                         AppLogger.Error($"Clone repository failed for repo '{SelectedRepo.Name}'.", ex);
741.                         return false;
742.                     }
743.                     finally
744.                     {
745.                         _cts?.Dispose();
746.                         _cts = null;
747.                         IsBusy = false;
748.                     }
749.                 }
750. 
751.                 private async Task<bool> EnsureCommitIdentityReadyAsync()
752.                 {
753.                     if (SelectedRepo is null)
754.                         return false;
755. 
756.                     AppLogger.Info($"Validating commit identity readiness for '{SelectedRepo.Name}'.");
757.                     var ready = await _gitService.ApplyRecommendedWorkspaceGitSettingsAsync(
758.                         SelectedRepo.GitRepoPath,
759.                         SelectedRepo.GitUserNameOverride,
760.                         SelectedRepo.GitUserEmailOverride,
761.                         AppendLog);
762. 
763.                     if (ready)
764.                         return true;
765. 
766.                     OperationStatus = $"Commit blocked: git identity setup required ({SelectedRepo.Name})";
767.                     MessageBox.Show(
768.                         "Commit is blocked because git user identity is incomplete.\n\n" +
769.                         "Set global git user.name/user.email in Dependencies or set both per-controller override fields in Edit Controller.",
770.                         "Git identity required",
771.                         MessageBoxButton.OK,
772.                         MessageBoxImage.Warning);
773.                     AppLogger.Warn($"Commit blocked for '{SelectedRepo.Name}' due to missing/invalid git identity.");
774.                     return false;
775.                 }
776. 
777.             default:
778.                 return false;
779.         }
780.     }
781. 
782.     /// <summary>
783.     /// Writes the current in-memory state back to <c>config.json</c>.
784.     /// </summary>
785.     private void PersistConfig()
786.     {
787.         _config.L5xGitExePath = L5xGitExePath;
788.         _config.Repos = [.. Repos.Select(r => r.ToModel())];
789.         _configService.Save(_config);
790.     }
791. }
