                         return false;
                     }

                     IsBusy = true;
                     _cts = new CancellationTokenSource();
                     try
                     {
                         OperationStatus = $"Repository setup step 1/1: Cloning repository ({SelectedRepo.Name})";
                         AppendLog("[phase] Repository setup — cloning repository.");
                         var cloned = await _cliService.CloneRepositoryAsync(
                             cloneWindow.RemoteUrl,
                             cloneWindow.DestinationPath,
                             AppendLog,
                             _cts.Token);

                         if (!cloned)
                         {
                             OperationStatus = $"Clone failed: {SelectedRepo.Name}";
                             return false;
                         }

                         if (!string.Equals(SelectedRepo.GitRepoPath, cloneWindow.DestinationPath, StringComparison.Ordinal))
                         {
                             SelectedRepo.GitRepoPath = cloneWindow.DestinationPath;
                             PersistConfig();
                             AppLogger.Info($"Updated repo git path after clone: {cloneWindow.DestinationPath}");
                         }

                         cloned = await _gitService.ApplyRecommendedWorkspaceGitSettingsAsync(
                             SelectedRepo.GitRepoPath,
                             SelectedRepo.GitUserNameOverride,
                             SelectedRepo.GitUserEmailOverride,
                             AppendLog,
                             _cts.Token);
                         if (!cloned)
                         {
                             OperationStatus = $"Repository clone completed, but git identity setup failed: {SelectedRepo.Name}";
                             return false;
                         }

                         OperationStatus = $"Repository cloned: {SelectedRepo.Name}";
                         return true;
                     }
                     catch (OperationCanceledException)
                     {
                         AppendLog("[cancelled] Clone repository was cancelled.");
                         OperationStatus = $"Clone cancelled: {SelectedRepo.Name}";
                         AppLogger.Info($"Clone repository cancelled for '{SelectedRepo.Name}'.");
                         return false;
                     }
                     catch (Exception ex)
                     {
                         AppendLog($"[error] {ex.Message}");
                         OperationStatus = $"Clone failed: {SelectedRepo.Name}";
                         AppLogger.Error($"Clone repository failed for repo '{SelectedRepo.Name}'.", ex);
                         return false;
                     }
                     finally
                     {
                         _cts?.Dispose();
                         _cts = null;
                         IsBusy = false;
                     }
                 }

                 private async Task<bool> EnsureCommitIdentityReadyAsync()
                 {
                     if (SelectedRepo is null)
                         return false;

                     AppLogger.Info($"Validating commit identity readiness for '{SelectedRepo.Name}'.");
                     var ready = await _gitService.ApplyRecommendedWorkspaceGitSettingsAsync(
                         SelectedRepo.GitRepoPath,
                         SelectedRepo.GitUserNameOverride,
                         SelectedRepo.GitUserEmailOverride,
                         AppendLog);

                     if (ready)
                         return true;

                     OperationStatus = $"Commit blocked: git identity setup required ({SelectedRepo.Name})";
                     MessageBox.Show(
                         "Commit is blocked because git user identity is incomplete.\n\n" +
                         "Set global git user.name/user.email in Dependencies or set both per-controller override fields in Edit Controller.",
                         "Git identity required",
                         MessageBoxButton.OK,
                         MessageBoxImage.Warning);
                     AppLogger.Warn($"Commit blocked for '{SelectedRepo.Name}' due to missing/invalid git identity.");
                     return false;
                 }

             default:
                 return false;
         }
     }

     /// <summary>
     /// Writes the current in-memory state back to <c>config.json</c>.
     /// </summary>
     private void PersistConfig()
     {
         _config.L5xGitExePath = L5xGitExePath;
         _config.Repos = [.. Repos.Select(r => r.ToModel())];
         _configService.Save(_config);
     }
 }

