 using System.IO;
 using ABLogixGitManager.Models;
 using ABLogixGitManager.Services;
 using ABLogixGitManager.Tests;
 using FlaUI.Core;
 using FlaUI.Core.AutomationElements;
 using FlaUI.Core.Tools;
 using FlaUI.UIA3;

 namespace ABLogixGitManager.UiTests;

 /// <summary>
 /// Not a correctness test — this drives the real, already-built app through the screens
 /// documented in the <c>docs/</c> Obsidian wiki and saves captures directly into
 /// <c>docs/assets/screenshots/</c> so the wiki pages can embed real, current screenshots
 /// instead of stale or hand-edited images.
 /// </summary>
 /// <remarks>
 /// <para>
 /// Each screenshot is cropped to the specific window (or dialog) being demonstrated via
 /// <see cref="WindowCapture"/> — not a full-desktop capture — so the resulting image doesn't show
 /// unrelated windows (e.g. the code editor) behind the app. See <see cref="WindowCapture"/> for why
 /// this requires making the test process itself DPI-aware.
 /// </para>
 /// <para>
 /// Requires an interactive Windows desktop session and a prior build of the main app. Not part
 /// of the default `dotnet test` run — see <c>tests/README.md</c>. Re-run this whenever a screen
 /// covered by the wiki changes visually, then re-review/re-commit the affected PNGs.
 /// </para>
 /// </remarks>
 public sealed class WikiScreenshotTests : IDisposable
 {
     private readonly string _configPath;
     private readonly string? _backupConfigJson;
     private readonly TempGitRepo _repo = new();
     private readonly Xunit.Abstractions.ITestOutputHelper _output;
     private Application? _app;
     private UIA3Automation? _automation;

     private static readonly string ScreenshotDir = Path.Combine(
         FindRepoRoot(), "docs", "assets", "screenshots");

     public WikiScreenshotTests(Xunit.Abstractions.ITestOutputHelper output)
     {
         _output = output;
         _configPath = Path.Combine(
             Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
             "ABLogixGitManager", "config.json");

         _backupConfigJson = File.Exists(_configPath) ? File.ReadAllText(_configPath) : null;

         _repo.WriteFile("MainProgram.txt", "rung 0 : examine ON, energize coil");
         _repo.Commit("Initial import from ACD export");
         _repo.WriteFile("MainProgram.txt", "rung 0 : examine ON, energize coil\r\nrung 1 : timer preset 5000ms");
         _repo.Commit("Add conveyor delay timer");

         var config = new AppConfig
         {
             // Non-empty so the app does not schedule the first-run Settings dialog on startup.
             L5xGitExePath = @"C:\does-not-exist\l5xgit.exe",
             Repos =
             [
                 new RepoEntry
                 {
                     Name = "Line 3 Conveyor Controller",
                     AcdFilePath = @"C:\does-not-exist\Line3Conveyor.ACD",
                     GitRepoPath = _repo.RepoPath,
                 },
             ],
         };
         new AppConfigService().Save(config);

         Directory.CreateDirectory(ScreenshotDir);
         _output.WriteLine($"Wiki screenshots will be written to: {ScreenshotDir}");
     }

     /// <summary>Walks up from the test assembly's output directory to find the repo root (marked by <c>docs/</c> and <c>.git</c>).</summary>
     private static string FindRepoRoot()
     {
         var dir = AppContext.BaseDirectory;
         var current = new DirectoryInfo(dir);
         while (current is not null)
         {
             if (Directory.Exists(Path.Combine(current.FullName, ".git")))
                 return current.FullName;
             current = current.Parent;
         }

         throw new InvalidOperationException($"Could not locate repository root from '{dir}'.");
     }

